const q = $input.first().json.query || {};
const ok = q['hub.verify_token'] === $env.META_VERIFY_TOKEN;
return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

// Normaliza WhatsApp / Instagram DM / Messenger a un shape común.
// Meta manda 'entry' con 'changes' (WhatsApp) o 'messaging' (IG/Messenger).
const body = $input.first().json.body || {};
const out = [];

for (const entry of (body.entry || [])) {
  // WhatsApp Cloud API
  for (const change of (entry.changes || [])) {
    const val = change.value || {};
    for (const msg of (val.messages || [])) {
      if (msg.type !== 'text') continue; // TODO: soportar audio/imagen si hace falta
      const contact = (val.contacts || [])[0] || {};
      out.push({
        canal: 'whatsapp',
        from: msg.from,
        nombre: contact.profile ? contact.profile.name : undefined,
        texto: msg.text ? msg.text.body : '',
        threadId: msg.from,
        raw: msg,
      });
    }
  }
  // Instagram DM / Messenger (comparten el shape 'messaging')
  for (const m of (entry.messaging || [])) {
    if (!m.message || m.message.is_echo) continue; // ignora eco de mensajes propios
    const canal = body.object === 'instagram' ? 'instagram' : 'messenger';
    out.push({
      canal,
      from: m.sender ? m.sender.id : undefined,
      texto: m.message.text || '',
      threadId: m.sender ? m.sender.id : undefined,
      raw: m,
    });
  }
}

return out.map((j) => ({ json: j }));

const j = $input.first().json;
return [{ json: {
  canal: 'gmail',
  from: j.from,
  nombre: (j.from || '').replace(/<.*/, '').trim(),
  texto: j.text || j.snippet || '',
  threadId: j.threadId,
  messageId: j.id,
  raw: j,
} }];

// Solo Gmail trae email de forma confiable. WhatsApp/IG/Messenger dan un id de canal (wa_id / psid / igsid), no un email.
// TODO backend: si se quiere CRM unificado, extender POST /api/n8n/contacts para aceptar phone/external_id además de email.
const j = $input.first().json;
if (j.canal !== 'gmail') return [];
const emailMatch = (j.from || '').match(/<([^>]+)>/);
const email = emailMatch ? emailMatch[1] : j.from;
return [{ json: { email, name: j.nombre, source: 'chatbot-' + j.canal } }];

