  "properties": {
    "respuesta": { "type": "string", "description": "Lo que se le responde a la persona. Vacío o cálido de espera si escalar=true." },
    "escalar": { "type": "boolean", "description": "true si es obra/diseño privado, plata grande, caso raro, o no está seguro." },
    "motivo": { "type": "string", "description": "Por qué escala, para el aviso interno a Jonatan." }
  }
}

