// El Output Parser ya deja $json.output como objeto {respuesta, escalar, motivo}.
// Si por lo que sea vino como string, lo parseamos a mano.
let out = $json.output;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = { respuesta: out, escalar: false, motivo: '' }; } }
return [{ json: { ...($input.first().json), respuesta: out.respuesta, escalar: !!out.escalar, motivo: out.motivo || '' } }];

